import pygame

from constants import WIDTH, HEIGHT, FPS
from game import TetrisGame
from ui import draw_game


def main():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    pygame.display.set_caption("Tetris")
    clock = pygame.time.Clock()
    font = pygame.font.SysFont("consolas", 26, bold=True)
    small = pygame.font.SysFont("consolas", 16)

    game = TetrisGame()
    drop_timer = pygame.time.get_ticks()
    running = True

    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_r:
                    game.reset()
                    drop_timer = pygame.time.get_ticks()
                elif event.key == pygame.K_p and not game.game_over:
                    game.paused = not game.paused
                elif not game.game_over and not game.paused:
                    if event.key == pygame.K_LEFT:
                        game.move(-1)
                    elif event.key == pygame.K_RIGHT:
                        game.move(1)
                    elif event.key == pygame.K_DOWN:
                        if game.move(0, 1):
                            game.score += 1
                        drop_timer = pygame.time.get_ticks()
                    elif event.key == pygame.K_UP:
                        game.rotate_piece()
                    elif event.key == pygame.K_SPACE:
                        game.hard_drop()
                        drop_timer = pygame.time.get_ticks()

        now = pygame.time.get_ticks()
        if now - drop_timer >= game.drop_interval():
            game.tick()
            drop_timer = now

        draw_game(screen, game, font, small)
        pygame.display.flip()
        clock.tick(FPS)

    pygame.quit()


if __name__ == "__main__":
    main()
