import random

from constants import COLS, ROWS, LINE_SCORES, SHAPES


def rotate(shape):
    return [list(row) for row in zip(*shape[::-1])]


class Piece:
    def __init__(self, key=None):
        self.key = key or random.choice(list(SHAPES))
        self.shape = [row[:] for row in SHAPES[self.key]]
        self.x = (COLS - len(self.shape[0])) // 2
        self.y = 0

    @staticmethod
    def cells(shape, px, py):
        return [(px + c, py + r)
                for r, row in enumerate(shape)
                for c, v in enumerate(row) if v]


class TetrisGame:
    def __init__(self):
        self.reset()

    def reset(self):
        self.board = [[None] * COLS for _ in range(ROWS)]
        self.score = 0
        self.lines = 0
        self.level = 1
        self.game_over = False
        self.paused = False
        self.next_piece = Piece()
        self.spawn()

    def spawn(self):
        self.piece = self.next_piece
        self.next_piece = Piece()
        if self.collides(self.piece.shape, self.piece.x, self.piece.y):
            self.game_over = True

    def collides(self, shape, x, y):
        for cx, cy in Piece.cells(shape, x, y):
            if cx < 0 or cx >= COLS or cy >= ROWS:
                return True
            if cy >= 0 and self.board[cy][cx]:
                return True
        return False

    def move(self, dx, dy=0):
        if self.game_over or self.paused:
            return False
        if self.collides(self.piece.shape, self.piece.x + dx, self.piece.y + dy):
            return False
        self.piece.x += dx
        self.piece.y += dy
        return True

    def rotate_piece(self):
        if self.game_over or self.paused:
            return
        rotated = rotate(self.piece.shape)
        for kick in (0, -1, 1, -2, 2):
            if not self.collides(rotated, self.piece.x + kick, self.piece.y):
                self.piece.shape = rotated
                self.piece.x += kick
                return

    def hard_drop(self):
        if self.game_over or self.paused:
            return
        dist = 0
        while self.move(0, 1):
            dist += 1
        self.score += dist * 2
        self.lock()

    def tick(self):
        if self.game_over or self.paused:
            return
        if not self.move(0, 1):
            self.lock()

    def lock(self):
        for cx, cy in Piece.cells(self.piece.shape, self.piece.x, self.piece.y):
            self.board[cy][cx] = self.piece.key
        self.clear_lines()
        self.spawn()

    def clear_lines(self):
        kept = [row for row in self.board if any(cell is None for cell in row)]
        cleared = ROWS - len(kept)
        if cleared:
            self.board = [[None] * COLS for _ in range(cleared)] + kept
            self.lines += cleared
            self.score += LINE_SCORES[cleared] * self.level
            self.level = self.lines // 10 + 1

    def drop_interval(self):
        return max(100, 1000 - (self.level - 1) * 90)
